S = "Hakeem Force Academy"
QS = [
(S, "Who founded the political party Pakistan Tehreek-e-Insaf (PTI)?", ["Imran Khan", "Nawaz Sharif", "Asif Ali Zardari", "Altaf Hussain"], 0, "PTI was founded by Imran Khan in April 1996 in Lahore. He has remained its founder and leader since.", "Imran Khan became Prime Minister of Pakistan in August 2018 and was removed through a no-confidence vote in April 2022.", [4845, 575]),
(S, "Who is the chairman of Pakistan Tehreek-e-Insaf (PTI) as of 2026?", ["Barrister Gohar Ali Khan", "Imran Khan", "Shah Mahmood Qureshi", "Pervez Khattak"], 0, "Barrister Gohar Ali Khan was elected PTI chairman unopposed in December 2023 as a temporary arrangement. He is still reported as chairman in 2026.", "Imran Khan was chairman before 2023 and the party's founder; his camp still calls him the real chairman.", [1220]),
(S, "To which tribe did Muhammad bin Qasim belong?", ["Banu Thaqif", "Banu Hashim", "Banu Umayyah", "Banu Tamim"], 0, "Muhammad bin Qasim was born in Taif and belonged to the Banu Thaqif tribe. He conquered Sindh in 711-712 AD.", "He was a nephew of the Umayyad governor Hajjaj bin Yusuf, who also belonged to Thaqif.", [2796]),
(S, "A quantity that can change its value is known as what?", ["Variable", "Constant", "Coefficient", "Exponent"], 0, "A variable is a symbol or quantity whose value can vary. A constant, by contrast, keeps a fixed value.", "In algebra, letters such as x and y are commonly used as variables.", [3000]),
(S, "What is a scalar quantity?", ["A quantity with magnitude only and no direction", "A quantity with both magnitude and direction", "A quantity with direction only", "A quantity that is always constant"], 0, "A scalar is fully described by its magnitude (size) alone. Examples are mass, time, speed and temperature.", "A quantity with both magnitude and direction, such as velocity or force, is called a vector.", [3005]),
(S, "What is a quarter of 1/10 of 9?", ["0.225", "2.25", "0.9", "0.0225"], 0, "1/10 of 9 = 0.9. A quarter of 0.9 = 0.9 divided by 4 = 0.225.", "A quarter of a number means dividing it by 4.", [3001]),
(S, "What is a quarter of 1/20?", ["1/80", "1/5", "1/24", "1/40"], 0, "A quarter of 1/20 = 1/20 x 1/4 = 1/80.", "Multiplying two fractions means multiplying numerators together and denominators together.", [866]),
(S, "What is a quarter of 10% of 120?", ["3", "30", "4", "12"], 0, "10% of 120 = 12. A quarter of 12 = 12 divided by 4 = 3.", "10% of a number is the same as one tenth of it.", [455]),
(S, "What is a quarter of 90?", ["22.5", "30", "18", "25"], 0, "A quarter of 90 = 90 divided by 4 = 22.5.", "A quarter equals 25%, so 25% of 90 is also 22.5.", [3002]),
(S, "What is the quarter of 9?", ["2.25", "3", "2.5", "4.5"], 0, "A quarter of 9 = 9 divided by 4 = 2.25.", "Half of 9 is 4.5, and half of that is 2.25.", [3655]),
(S, "What was the old name of Quetta?", ["Shal (Shalkot)", "Kandahar", "Sibi", "Zhob"], 0, "Quetta was historically known as Shal or Shalkot. The name Quetta comes from the word Kwatkot, meaning fort.", "Quetta is the capital of Balochistan and is called the Fruit Garden of Pakistan.", [3611]),
(S, "Quraish, the tribe of the Holy Prophet (PBUH), were residents of which city?", ["Makkah", "Madinah", "Taif", "Jeddah"], 0, "The Quraish were the dominant tribe of Makkah and guardians of the Kaaba. The Holy Prophet (PBUH) was born among them.", "The Muslims migrated from Makkah to Madinah in 622 AD.", [2633]),
(S, "What is the meaning of Radd-ul-Fasaad, the name of the military operation launched in 2017?", ["Elimination of discord and strife", "Defence of the border", "Thunder strike", "Swift response"], 0, "Radd-ul-Fasaad is Arabic for repelling or eliminating discord (strife). The operation aimed to eliminate terrorism across Pakistan.", "Operation Radd-ul-Fasaad was launched by the Pakistan Army in February 2017.", [3521, 3522]),
(S, "What is the antonym of radiant?", ["Dull", "Bright", "Shining", "Glowing"], 0, "Radiant means shining brightly, so its opposite is dull, which means lacking brightness.", "Radiant also describes a person who looks very happy, as in a radiant smile.", [3165]),
(S, "What is the meaning of radiant?", ["Shining brightly", "Very weak", "Dark and gloomy", "Extremely cold"], 0, "Radiant means sending out light or shining brightly. It can also mean glowing with joy.", "The word comes from the Latin radiare, meaning to emit rays.", [3523]),
(S, "What is the radius of the incircle of a triangle called?", ["Inradius", "Circumradius", "Exradius", "Apothem"], 0, "The circle drawn inside a triangle touching all three sides is the incircle, and its radius is called the inradius. The circumradius belongs to the circle through all three vertices.", "For a triangle, inradius = Area divided by semi-perimeter.", [3659]),
(S, "The famous Pashto Sufi poet Rahman Baba is associated with which city?", ["Peshawar", "Quetta", "Swat", "Kohat"], 0, "Rahman Baba (17th century) lived near Peshawar and is buried in Hazar Khwani, Peshawar. He is among the greatest Pashto poets.", "His poetry collection is known as the Diwan of Rahman Baba.", [2626]),
(S, "In which year was Choudhry Rahmat Ali, who coined the name Pakistan, born?", ["1897", "1885", "1905", "1877"], 0, "Choudhry Rahmat Ali was born on 16 November 1897 in Balachaur, Punjab. He coined the name Pakistan in 1933.", "He died in Cambridge, England, in February 1951.", [4083]),
(S, "Which angel is in charge of rain and provision according to Islamic belief?", ["Hazrat Mikail (AS)", "Hazrat Jibrail (AS)", "Hazrat Israfil (AS)", "Hazrat Izrail (AS)"], 0, "Hazrat Mikail (AS) is the angel entrusted with rain, vegetation and sustenance. Jibrail brings revelation, Israfil blows the Trumpet and Izrail takes souls.", "Mikail is also spelled Mika'il and is mentioned by name in Surah Al-Baqarah.", [1612, 891, 4247, 4251]),
(S, "For how much was Kashmir sold to Gulab Singh under the Treaty of Amritsar (1846)?", ["75 lakh Nanakshahi rupees", "50 lakh rupees", "1 crore rupees", "25 lakh rupees"], 0, "By the Treaty of Amritsar, the British sold Kashmir to Gulab Singh Dogra for 75 lakh (7.5 million) Nanakshahi rupees.", "Gulab Singh founded the Dogra dynasty that ruled Jammu and Kashmir until 1947.", [1680]),
]
